export function createAudio(){let ctx,master;function init(){if(!ctx){ctx=new AudioContext();master=ctx.createGain();master.gain.value=.18;master.connect(ctx.destination);}ctx.resume();}function tone(freq,dur=.4,volume=.3,type='sine'){if(!ctx)return;const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,ctx.currentTime);g.gain.setValueAtTime(volume,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+dur);o.connect(g);g.connect(master);o.start();o.stop(ctx.currentTime+dur);}function noise(dur,volume,cutoff){if(!ctx)return;const b=ctx.createBuffer(1,ctx.sampleRate*dur,ctx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/a.length,2);const source=ctx.createBufferSource();source.buffer=b;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=cutoff;const gain=ctx.createGain();gain.gain.value=volume;source.connect(filter);filter.connect(gain);gain.connect(master);source.start();}
return{init,mute:v=>{if(master)master.gain.value=v?0:.18;},gesture:k=>{if(k==='stomp'){tone(63,.4,.6);noise(.25,.3,450);}if(k==='sway')tone(220,.9,.08);if(k==='sing'){tone(261.63,2,.15);tone(392,2,.1);tone(523.25,2,.07);}if(k==='call')noise(2.3,.6,160);if(k==='hug')tone(174.6,1.5,.12);if(k==='sleeve')noise(.6,.05,1500);},chapter:n=>{if(n===2){tone(261.63,4,.14);tone(329.63,4,.09);tone(392,4,.1);}if(n===5){tone(174.6,5,.12);tone(261.63,5,.08);}},callback:()=>{tone(349.23,2,.15);tone(523.25,2,.07);}};}
